script:
// Using root_element as parent scope
const calendar = root_element.querySelector(".memento-calendar");

if (calendar) {
    const monthElement = calendar.querySelector(".memento-calendar-month");
    const daysElement = calendar.querySelector(".memento-calendar-days");
    const previousButton = calendar.querySelector("[data-calendar-prev]");
    const nextButton = calendar.querySelector("[data-calendar-next]");

    let selectedDate = new Date();
    const today = new Date();

    function getStartOfWeek(date) {
        const d = new Date(date);
        const day = d.getDay();
        const diff = d.getDate() - (day === 0 ? 6 : day - 1);
        return new Date(d.setDate(diff));
    }

    function renderWeeklyCalendar() {
        daysElement.innerHTML = "";

        const monday = getStartOfWeek(selectedDate);
        const monthName = new Intl.DateTimeFormat("en-US", { month: "long" }).format(monday);

        // Updates "Loading..." to the active month name dynamically
        monthElement.textContent = monthName;

        for (let i = 0; i < 7; i++) {
            const currentDay = new Date(monday);
            currentDay.setDate(monday.getDate() + i);

            const dayElement = document.createElement("span");
            dayElement.className = "memento-calendar-day";
            dayElement.textContent = currentDay.getDate();

            if (
                currentDay.getDate() === today.getDate() &&
                currentDay.getMonth() === today.getMonth() &&
                currentDay.getFullYear() === today.getFullYear()
            ) {
                dayElement.classList.add("today");
            }

            daysElement.appendChild(dayElement);
        }
    }

    if (previousButton) {
        previousButton.addEventListener("click", function () {
            selectedDate.setDate(selectedDate.getDate() - 7);
            renderWeeklyCalendar();
        });
    }

    if (nextButton) {
        nextButton.addEventListener("click", function () {
            selectedDate.setDate(selectedDate.getDate() + 7);
            renderWeeklyCalendar();
        });
    }

    renderWeeklyCalendar();
}

style:
@import url('https://fonts.googleapis.com/css2?family=Petit+Formal+Script&display=swap');

/* =========================================
   MEMENTO HEADER (CENTERED TITLE)
   ========================================= */
.memento-page-header {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 24px;
    box-sizing: border-box;
}

.memento-page-title {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
}

.memento-page-title h1 {
    margin: 0;
    text-align: center;
    font-size: 44px;
    font-weight: 900;
    color: #31183b;
    letter-spacing: normal;
    font-family: 'Petit Formal Script', cursive, sans-serif;
}

/* =========================================
   CALENDAR COMPONENT (INSIDE HERO RIGHT)
   ========================================= */
.memento-header-calendar {
    position: absolute;
    top: 20px;
    right: 30px;
    width: 280px;
    z-index: 10;
}

.memento-calendar {
    width: 100%;
    padding: 12px 15px 13px;
    box-sizing: border-box;
    background: linear-gradient(145deg, rgba(255, 255, 255, 0.96), rgba(250, 244, 248, 0.94));
    border: 1px solid rgba(68, 42, 71, 0.10);
    border-radius: 16px;
    box-shadow: 0 4px 14px rgba(68, 42, 71, 0.06), 0 1px 3px rgba(68, 42, 71, 0.04);
    backdrop-filter: blur(10px);
}

.memento-calendar-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 28px;
    margin-bottom: 8px;
}

.memento-calendar-month {
    flex: 1;
    font-size: 13px;
    font-weight: 700;
    color: #442a47;
    text-align: center;
    letter-spacing: 0.2px;
}

.memento-calendar-nav {
    width: 27px;
    height: 27px;
    padding: 0;
    border: none;
    border-radius: 8px;
    background: rgba(68, 42, 71, 0.06);
    color: #442a47;
    font-size: 18px;
    line-height: 1;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.2s ease, transform 0.2s ease, color 0.2s ease;
}

.memento-calendar-nav:hover {
    background: #442a47;
    color: #ffffff;
    transform: scale(1.05);
}

.memento-calendar-weekdays {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 2px;
    margin-bottom: 3px;
}

.memento-calendar-weekdays span {
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 9px;
    font-weight: 600;
    color: #a17f94;
    text-transform: uppercase;
}

.memento-calendar-days {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    align-items: center;
    gap: 4px;
}

.memento-calendar-day {
    width: 28px;
    height: 28px;
    margin: auto;
    padding: 0;
    border: none;
    border-radius: 50%;
    background: transparent;
    color: #633b52;
    font-size: 10px;
    font-weight: 500;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

.memento-calendar-day:hover {
    background: rgba(68, 42, 71, 0.08);
    color: #442a47;
    transform: scale(1.08);
}

.memento-calendar-day.today {
    background: #442a47;
    color: #ffffff;
    font-weight: 700;
    box-shadow: 0 3px 8px rgba(68, 42, 71, 0.20);
}

.memento-calendar-day.today:hover {
    background: #442a47;
    color: #ffffff;
}

/* =========================================
   HERO CORE CONTAINER & GRAPHICS
   ========================================= */
.memento-hero {
    position: relative;
    width: 100%;
    min-height: 210px; 
    overflow: hidden;
    border-radius: 12px;
    background: linear-gradient(105deg, #f4eef5 0%, #f6eaf0 35%, #faf1f3 65%, #fff4ee 100%);
    color: #442a47; 
    padding: 30px 32px;
    box-sizing: border-box;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

.memento-hero-content {
    position: relative;
    z-index: 5;
    flex: 1;
    max-width: 55%;
}

.memento-brand {
    display: flex;
    align-items: center;
    gap: 14px;
}

.memento-logo {
    width: 42px;
    height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 10px;
    background: rgba(68, 42, 71, 0.08);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(68, 42, 71, 0.15);
    color: #442a47;
}

.memento-subtitle {
    margin: 0;
    font-size: 14px;
    font-weight: 500;
    color: #633b52;
}

.memento-welcome {
    margin-top: 20px;
}

.memento-welcome h2 {
    margin: 0 0 6px;
    font-size: 16px;
    font-weight: 600;
    color: #442a47;
}

.memento-welcome p {
    margin: 0;
    font-size: 12.5px;
    line-height: 1.5;
    color: #633b52;
    max-width: 480px;
}

/* Track Project Button */
.memento-btn-track {
    text-align:center;
    position: relative;
    display: inline-flex;
    margin-top: 10px;
    align-items: center;
    gap: 15px;
    background: #442a47;
    color: #ffffff !important;
    text-decoration: none !important;
    padding: 10px 25px;
    font-size: 13px;
    font-weight: 600;
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 4px 14px rgba(68, 42, 71, 0.15);
    transition: transform 0.2s cubic-bezier(0.25, 1, 0.5, 1), 
                box-shadow 0.2s cubic-bezier(0.25, 1, 0.5, 1);
}

.memento-btn-track::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.15), transparent);
    transition: none;
}

.memento-btn-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.memento-btn-track:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(68, 42, 71, 0.28);
}

.memento-btn-track:hover::before {
    left: 100%;
    transition: left 0.65s cubic-bezier(0.25, 1, 0.5, 1);
}

.memento-btn-track:hover .memento-btn-icon {
    transform: translateX(4px) scale(1.1);
}

.memento-btn-track:active {
    transform: translateY(1px);
    box-shadow: 0 2px 8px rgba(68, 42, 71, 0.2);
}

/* Graphics Wrapper (Quote, Sun, Mountains) */
.memento-graphics-wrapper {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    width: 50%;
    z-index: 2;
    overflow: hidden;
}

.memento-sun {
    position: absolute;
    width: 56px;
    height: 56px;
    right: 70px;
    bottom: 45px;
    border-radius: 50%;
    background: #ffeba2;
    z-index: 1;
    box-shadow: 0 0 35px rgba(255, 235, 162, 0.5);
}

.memento-mountains {
    position: absolute;
    bottom: -2px;
    right: 0;
    width: 100%;
    height: 100%;
    z-index: 2;
    pointer-events: none;
}

.memento-quote {
    position: absolute;
    z-index: 4;
    right: 325px;
    top: 105px;
    text-align: center;
    font-family: 'Georgia', serif;
    font-size: 14px;
    font-style: italic;
    color: #633b52; 
    line-height: 1.3;
    pointer-events: none;
}

.memento-quote span {
    display: block;
}

.quote-text-top {
    font-weight: 400;
}

.quote-text-bottom {
    font-size: 15px;
    font-weight: 600;
    padding-left: 10px;
}
